      out.write("\r\n");
      out.write("    if (\r\n");
      out.write("        (email === user.email && password === user.password) ||\r\n");
      out.write("        (email === defaultUser.email && password === defaultUser.password) ||\r\n");
      out.write("        (email === 'admin' && password === '123456')\r\n");
